package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen1Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testDivide_NormalValues() {
        Complex c = new Complex(10.0, 5.0);
        Complex result = c.divide(2.0);
        Assert.assertEquals(5.0, result.getReal(), EPSILON);
        Assert.assertEquals(2.5, result.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_NaN_Input() {
        Complex c = new Complex(1.0, 1.0);
        Complex result = c.divide(Double.NaN);
        Assert.assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_NaN_Complex() {
        Complex c = Complex.NaN;
        Complex result = c.divide(2.0);
        Assert.assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_ZeroDivisor_NonZeroComplex() {
        Complex c = new Complex(1.0, 1.0);
        Complex result = c.divide(0.0);
        // According to code: isZero ? NaN : INF
        // Since c is not zero, it returns INF
        Assert.assertTrue(result.isInfinite());
        Assert.assertFalse(result.isNaN());
    }

    @Test
    public void testDivide_ZeroDivisor_ZeroComplex() {
        Complex c = new Complex(0.0, 0.0);
        Complex result = c.divide(0.0);
        // Since c is zero, it returns NaN
        Assert.assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_InfiniteDivisor_FiniteComplex() {
        Complex c = new Complex(1.0, 1.0);
        Complex result = c.divide(Double.POSITIVE_INFINITY);
        // !isInfinite() ? ZERO : NaN
        Assert.assertEquals(0.0, result.getReal(), EPSILON);
        Assert.assertEquals(0.0, result.getImaginary(), EPSILON);
        Assert.assertFalse(result.isInfinite());
        Assert.assertFalse(result.isNaN());
    }

    @Test
    public void testDivide_InfiniteDivisor_InfiniteComplex() {
        Complex c = new Complex(Double.POSITIVE_INFINITY, 1.0);
        Complex result = c.divide(Double.POSITIVE_INFINITY);
        // Since c is infinite, returns NaN
        Assert.assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_NegativeDivisor() {
        Complex c = new Complex(10.0, -5.0);
        Complex result = c.divide(-2.0);
        Assert.assertEquals(-5.0, result.getReal(), EPSILON);
        Assert.assertEquals(2.5, result.getImaginary(), EPSILON);
    }
}
